});

await test("STT evals: off by default, on by option or NEUROLINK_STT_EVAL_ENABLED=1, bounded in bytes, and scoped to the caller", async () => {
  const segment = (id: string, text: string) => ({
    id,
    source: "primary",
    model: "m",
    participant_identity: "alice",
    text,
    received_at: 1_792_000_000,
  });
  const batch = (call: string, text = "hello there") => ({
    call_id: call,
    batch: 1,
    models: { primary: "a", shadow: "b" },
    segments: [segment(`${call}-1`, text)],
  });

  const off = await startAdapter({
    framework: "hono",
    routes: { allowUnauthenticated: true },
  });
  try {
    assertEqual(
      (await http("GET", `${off.url}/v1/evals/stt`)).status,
      404,
      "the collector is not mounted by default",
    );
  } finally {
    await off.stop();
  }

  process.env.NEUROLINK_STT_EVAL_ENABLED = "1";
  let viaEnv: RunningAdapter | undefined;
  try {
    viaEnv = await startAdapter({
      framework: "hono",
      routes: { allowUnauthenticated: true },
    });
    assertEqual(
      (await http("GET", `${viaEnv.url}/v1/evals/stt`)).status,
      200,
      "NEUROLINK_STT_EVAL_ENABLED=1 mounts the collector",
    );
  } finally {
    delete process.env.NEUROLINK_STT_EVAL_ENABLED;
    await viaEnv?.stop();
  }

  const bounded = await startAdapter({
    framework: "hono",
    routes: {
      allowUnauthenticated: true,
      transcribe: { evals: { maxBytes: 600 } },
    },
  });
  try {
    const filler = "x".repeat(400);
    for (const call of ["c-1", "c-2", "c-3"]) {
      const reply = await http("POST", `${bounded.url}/v1/evals/stt`, {
        body: batch(call, filler),
      });
      assertEqual(reply.status, 200, "a batch is accepted");
    }
    const list = await http("GET", `${bounded.url}/v1/evals/stt`);
    const calls = (
      (list.json as { data?: { calls?: Array<{ call_id: string }> } }).data
        ?.calls ?? []
    ).map((call) => call.call_id);
    assert(
      calls.length < 3,
      "the byte budget must evict the oldest call once exceeded",
    );
    assert(calls.includes("c-3"), "the newest call is kept");
    assert(!calls.includes("c-1"), "the oldest call is evicted first");
  } finally {
    await bounded.stop();
  }

  const scoped = await startAdapter({
    framework: "hono",
    config: { carryMiddlewareState: true },
    middleware: [
      createAuthMiddleware({
        type: "bearer",
        skipDevPlayground: false,
        validate: async (token) => ({ id: token }),
      }),
    ],
    routes: { transcribe: { evals: {} } },
  });
  try {
    const asAlice = { authorization: "Bearer alice" };
    const asBob = { authorization: "Bearer bob" };
    assertEqual(
      (
        await http("POST", `${scoped.url}/v1/evals/stt`, {
          body: batch("owned"),
          headers: asAlice,
        })
      ).status,
      200,
      "the owner posts a call",
    );
    const bobList = await http("GET", `${scoped.url}/v1/evals/stt`, {
      headers: asBob,
    });
    const bobCalls = (
      (bobList.json as { data?: { calls?: Array<{ call_id: string }> } }).data
        ?.calls ?? []
    ).map((call) => call.call_id);
    assert(
      !bobCalls.includes("owned"),
      "another caller does not list the call",
    );
    assertEqual(
      (
        await http("GET", `${scoped.url}/v1/evals/stt/owned`, {
          headers: asBob,
        })
      ).status,
      404,
      "another caller cannot read the call",
    );
    assertEqual(
      (
        await http("POST", `${scoped.url}/v1/evals/stt`, {
          body: batch("owned"),
          headers: asBob,
        })
      ).status,
      403,
      "another caller cannot append to the call",
    );
    assertEqual(
      (
        await http("GET", `${scoped.url}/v1/evals/stt/owned`, {
          headers: asAlice,
        })
      ).status,
      200,
      "the owner reads the call",
    );
  } finally {
    await scoped.stop();
  }
});

await runSuite();

#!/usr/bin/env tsx
/**
 * Continuous Test Suite: Tool-layer security hardening (2026-10)
 *
 * Proves the tool-layer fixes of the 2026-10 security hardening:
 *
 * - HITL confirmation runs for the built-in `writeFile` and
 *        `executeBashCommand` tools when a model calls them; a denial leaves
 *        no side effect; an approval runs once with the confirmation's
 *        arguments; the bash tool's description matches that behaviour.
 * - A host-registered JSON Schema tool whose description, default,
 *        const, enum, property names and pattern are hostile is converted
 *        without evaluating any of it: nothing executes, nothing throws, the
 *        tool reaches the wire with its properties.
 * - A `pattern` that can backtrack catastrophically is dropped from a
 *        converted schema and from a remote MCP tool's schema before the
 *        validator is built, so a 28-character argument validates in
 *        milliseconds instead of seconds.
 * - Two external servers offering the same tool name both stay callable;
 *        the later one is qualified as `<serverId>__<tool>` and a warning
 *        names both servers.
 * - `calculateMath` evaluates arithmetic with a parser, not `Function`.
 * - A `__proto__` key in model JSON leaves `structuredData` with
 *        `Object.prototype` and no inherited fields.
 * - A `$regex` RAG filter with a ReDoS pattern is refused quickly while
 *        a benign pattern still matches.
 *
 * Determinism exception (CLAUDE.md rule 15). This suite imports from `src/`,
 * never from `dist/`, and is listed in the `neurolink/e2e-tests-only` allow
 * list. What determinism buys: the HITL cases need a model that calls
 * `writeFile` and `executeBashCommand` with chosen arguments on demand, which
 * a scripted loopback chat server provides and no live model guarantees; the
 * schema cases need hostile JSON Schemas fed to the converter, the external
 * MCP tool builder (`ToolsManager`, exported from no package entry point) and
 * a fake server list, since no real MCP server is wired here; the collision
 * case needs two servers that offer one name; `coerceJsonToSchema` and
 * `InMemoryVectorStore` are exercised on fixed payloads. Everything comes from
 * `src`; loopback stand-ins only, no keys and no network beyond 127.0.0.1.
 *
 * Every case fails on the pre-fix code: the HITL cases see zero confirmations
 * and a written file, the pattern cases take seconds, the collision case
 * finds one tool, the `__proto__` case reads `isAdmin === true`, and
 * `calculateMath` evaluates `globalThis` to an object.
 *
 * Run: pnpm exec tsx test/continuous-test-suite-security-tools.ts
 */
import "./helpers/credentialFreeEnv.js";
